UPDATE ai_model_api_usage_detail
SET settlement_delta_minor = #{settlementDeltaMinor,jdbcType=BIGINT}
WHERE usage_id = #{usageId,jdbcType=BIGINT}
  AND settlement_delta_minor IS NULL

WITH candidate(usage_id, reserved_quota_minor) AS ( VALUES
( #{candidate.usageId,jdbcType=BIGINT}, #{candidate.reservedQuotaMinor,jdbcType=BIGINT} )
) UPDATE ai_model_api_usage_detail detail SET settlement_delta_minor = -candidate.reserved_quota_minor FROM candidate WHERE detail.usage_id = candidate.usage_id AND detail.settlement_delta_minor IS NULL
